select device_code, date_trunc('hour', reading_ts) as hour_window, round(avg(humidity), 2) as avg_humidity, sum(case when device_code = 'DV-03' then status_bits else 0 end) as dv_03_status_bits, stddev_samp(temp_c) as temp_c_stddev, max(reading_ts) as last_seen, grouping(device_code) as grouping_id from device_readings group by rollup (device_code, date_trunc('hour', reading_ts));
